import React, {useState} from 'react'
import {useSelector, useDispatch} from 'react-redux'
import { actions } from './userSlice'
import {RootState, AppDispatch} from '../../app/store'

export default function Users() {
    const [userName, setUser] = useState('')
    const [userColor, setcolor] = useState('Red')
    const dispatch = useDispatch<AppDispatch>()
    const STATES = useSelector((state:RootState)=> state.user)
    const myColors = ['Red', 'Blue', 'Green', 'Purple']


    return (
        <div className="app--form">
            <div>
                <p>USERS: {STATES.users.length}</p>
                <p>PAYLOAD</p>
                <p>USER: {userName}</p>
                <p>COLOR: {userColor}</p>
                {STATES.showList ? <p>SHOW LIST IS TRUE</p> : <p>SHOW LIST IS FALSE</p>}
            </div>
            {!STATES.showList ?
            <section>
            <form 
                onSubmit={(e) => {
                e.preventDefault();
                dispatch(actions.addUser({ name: userName, color: userColor }));
                }}
            >
                <label>
                    User name:
                    <input
                    type="text"
                    value={userName}
                    onChange={(e) => setUser(e.target.value)}
                    placeholder="username"
                    />
                </label>
                <label>
                    Favorite color:
                    <select onChange={(e) => setcolor(e.target.value)}>
                        {myColors.map((color, index) => (
                            <option key={color+index}>{color}</option>
                        ))}
                        
                    </select>
                </label>
                <button type="submit">GO</button>
            </form>
            <button onClick={()=> dispatch(actions.toggleList())}>SHOW LIST OF USERS</button>
            </section>
            :
            <section>
                <ul>
                    {STATES.users.map((u, index) => (
                        <li 
                        className={u.color}
                        key={u.name}
                        >
                        {u.name} 

                        <button onClick={() => actions.deleteUser(index)}>X</button>
                        </li>
                    ))}
                </ul>
                <button onClick={()=> dispatch(actions.toggleList())}>ADD USER</button>
            </section>
            }
        </div>
    )
}
